class AsyncQueue {
  private items: any[] = []; private waiting: ((v:any)=>void)[] = [];
  push(v: any): Promise<void> {         // returns a promise: BACKPRESSURE by awaiting
    if (this.waiting.length) { this.waiting.shift()(v); return Promise.resolve(); }
    if (this.items.length >= this.cap) return new Promise(res => this.waiting.push(res)); // full: wait
    this.items.push(v); return Promise.resolve();
  }
  async pop(): Promise<any> {
    if (this.items.length) return this.items.shift();
    return new Promise(res => this.waiting.push(res));    // empty: await
  }
}
